module trip_planner ( input clk, input rst_n, input start, input [2:0] n, input [2:0] k, input [7:0][2:0] x, output reg [3:0] result, output reg done ); reg [1:0] state; reg [7:0] visited; reg [7:0][2:0] cycle_sizes; reg [2:0] cycle_count; reg [3:0] max_sum; reg [3:0] current_sum; reg [2:0] subset_mask; reg [2:0] num_cycles; reg [3:0] best_sum; always @(negedge rst_n) begin if (!rst_n) begin state <= 0; visited <= 0; cycle_sizes <= 0; cycle_count <=0; max_sum <=0; current_sum <=0; subset_mask <=0; best_sum <=0; done <=0; result <=0; end end always @(posedge clk) begin if (!rst_n) begin // Handle reset if needed, but using negedge above end else begin case (state) 0: // IDLE if (start == 1) begin state <= 1; // Move to DETECT end 1: // DETECT_CYCLES state <= 2; 2: // CALCULATE_RESULT if (k >= n) begin best_sum <= n; state <= 3; end else begin best_sum <=0; state <=3; end 3: // DONE done <= 1; result <= best_sum; endcase end end endmodule